function unsel(){sel.clear();document.querySelectorAll('.sel').forEach(x=>x.classList.remove('sel'));selbar()}
const clr=()=>{sel.clear();render()};
function selbar(){const b=$('#sb'),n=sel.size;b.classList.toggle('on',n>0);if(!n)return;b.innerHTML=`<b style="padding:0 8px">${n} выбрано</b><span class="dots">${Object.entries(S.cats).map(([k,c])=>`<button title="${esc(k)}" style="--c:${c}" onclick="bset('cat','${k}')"></button>`).join('')}</span><button onclick="bset('pri',0)">Обычное</button><button onclick="bset('pri',1)">Важное</button><button onclick="bset('pri',2)">Критичное</button><button onclick="bnext()">На завтра</button><button onclick="bdup()">Дублировать</button><button class="del" onclick="bdel()">Удалить</button><button onclick="clr()">×</button>`}
function bset(k,v){snap();S.ev.forEach(e=>{if(sel.has(e.id))e[k]=v});save();render();toast('Применено')}
function bdel(){snap();const n=sel.size;trashPut(S.ev.filter(e=>sel.has(e.id)));S.ev=S.ev.filter(e=>!sel.has(e.id));sel.clear();save();render();toast('Удалено: '+n)}
function bdup(){snap();[...S.ev].filter(e=>sel.has(e.id)).forEach(e=>{const c=structuredClone(e);c.id=uid();c.title+=' (копия)';S.ev.push(c)});save();render();toast('Скопировано')}
addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||dlg.open)return;if(e.key=='Escape'&&sel.size)clr();if((e.key=='Delete'||e.key=='Backspace')&&sel.size){e.preventDefault();bdel()}});
function vTasks(){const L=[...S.tasks].sort((a,b)=>a.done-b.done||b.p-a.p);return `<div class="card"><div class="bar"><input id="nt" placeholder="Новая задача" onkeydown="if(event.key=='Enter')addT()"><select id="np"><option value="0">Низкий<option value="1" selected>Средний<option value="2">Высокий</select><input type="date" id="nd"><button class="pri" onclick="addT()">Добавить</button></div>`+L.map(t=>`<div class="row ${t.done?'dn':''}"><input type="checkbox" ${t.done?'checked':''} onchange="togT('${t.id}',event)"><span class="sp">${esc(t.t)}</span><small>${t.due||''}</small><i class="pr p${t.p}">${['низ','сред','выс'][t.p]}</i><button onclick="S.tasks=S.tasks.filter(x=>x.id!='${t.id}');save();render()">✕</button></div>`).join('')+'</div>'}
function addT(){const t=$('#nt').value.trim();if(!t)return;S.tasks.push({id:Date.now()+'',t,p:+$('#np').value,due:$('#nd').value,done:0});save();render()}
function togT(id,ev){const t=S.tasks.find(x=>x.id==id);t.done=t.done?0:1;S.pts=(S.pts||0)+(t.done?1:-1)*(10+5*t.p);if(t.done)fx(ev.clientX||innerWidth/2,ev.clientY||innerHeight/2);save();render()}
const streak=h=>{let d=today(),n=0;if(!h.log.includes(d))d=add(d,-1);while(h.log.includes(d)){n++;d=add(d,-1)}return n};
function vHab(){return `<div class="card"><div class="bar"><input id="nh" placeholder="Новая привычка" onkeydown="if(event.key=='Enter')addH()"><button class="pri" onclick="addH()">Добавить</button></div>`+S.habits.map(h=>`<div class="row"><span class="sp">${esc(h.t)}</span>${[...Array(14)].map((_,i)=>`<div class="sq ${h.log.includes(add(today(),i-13))?'y':''}"></div>`).join('')}<b>${streak(h)} дн.</b><button class="${h.log.includes(today())?'on':''}" onclick="togH('${h.id}',event)">✓</button><button onclick="S.habits=S.habits.filter(x=>x.id!='${h.id}');save();render()">✕</button></div>`).join('')+'</div>'}
function addH(){const t=$('#nh').value.trim();if(t){S.habits.push({id:Date.now()+'',t,log:[]});save();render()}}
function togH(id,ev){const h=S.habits.find(x=>x.id==id),d=today(),i=h.log.indexOf(d);if(i<0){h.log.push(d);S.pts+=5;fx(ev.clientX,ev.clientY)}else{h.log.splice(i,1);S.pts-=5}save();render()}
function vGoals(){return `<div class="card"><div class="bar"><input id="ng" placeholder="Новая цель" onkeydown="if(event.key=='Enter')addG()"><button class="pri" onclick="addG()">Добавить</button></div>`+S.goals.map(g=>`<div class="row"><span class="sp">${esc(g.t)}</span><input type="range" value="${g.p}" onchange="setG('${g.id}',+this.value,event)"><b>${g.p}%</b><button onclick="S.goals=S.goals.filter(x=>x.id!='${g.id}');save();render()">✕</button></div>`).join('')+'</div>'}
function addG(){const t=$('#ng').value.trim();if(t){S.goals.push({id:Date.now()+'',t,p:0});save();render()}}
function setG(id,v,ev){S.goals.find(x=>x.id==id).p=v;if(v==100){fx(ev.clientX||innerWidth/2,ev.clientY||innerHeight/2);S.pts+=50}save();render()}
const sv2=(k,v)=>{S.set[k]=v;save();if(window.uiApply)uiApply();render()};
function vSet(){const s=S.set;return `${window.vLook?vLook():''}<div class="card"><h3>Время</h3><div class="bar">Часовой пояс UTC+ <input type="number" min="-12" max="14" step=".5" value="${s.tz}" style="width:80px" onchange="sv2('tz',+this.value)"></div></div><div class="card"><h3>Категории и цвета</h3>`+Object.entries(S.cats).map(([n,c])=>`<div class="row"><input type="color" value="${c}" onchange="S.cats['${n}']=this.value;save();render()"><span class="sp">${esc(n)}</span><button onclick="delete S.cats['${n}'];save();render()">✕</button></div>`).join('')+`<div class="bar"><input id="nc" placeholder="Новая категория"><button onclick="const v=$('#nc').value.replace(/['&quot;]/g,'').trim();if(v){S.cats[v]='#2f6bff';save();render()}">Добавить</button></div></div><div class="card"><h3>Данные и защита</h3><div class="bar"><button onclick="exp()">Экспорт</button><button onclick="ics()">Календарь .ics</button><input type="file" accept=".json" onchange="imp(this)"></div><small>Данные хранятся в этом браузере. Пароль защищает только вход на этом устройстве.</small></div><div class="card"><h3>Горячие клавиши</h3>N — новое событие · T — сегодня · ←/→ — назад/вперёд · D/W/M/Y — день/неделя/месяц/год · , — настройки · Ctrl+K — быстрый ввод · Ctrl+C / Ctrl+V — копировать выделенные · клик по теме слева — фильтр · / — поиск · клик или протяжка — новый этап · Shift+клик или рамка — выделить несколько · Delete — удалить выбранные · Ctrl+Z — отменить</div>`+`<div class="card"><h3>О сервисе</h3><div class="xn">IG calendar · версия <b>${VERSION}</b> · ${BUILD_DATE}</div></div>`}
const sha=async s=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))].map(b=>b.toString(16).padStart(2,'0')).join('');
async function setPw(){const p=await ui.prompt('Пароль на вход','Новый пароль (пусто — убрать)','',{type:'password',ok:'Сохранить'});if(p===null)return;S.set.pw=p?await sha(p):'';save()}
async function unlock(){if(await sha($('#lp').value)==S.set.pw)$('#lock').style.display='none';else $('#lp').value=''}
function exp(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(S)],{type:'application/json'}));a.download='ig-calendar.json';a.click()}
function imp(i){const r=new FileReader();r.onload=()=>{S=JSON.parse(r.result);save();render()};r.readAsText(i.files[0])}
function fx(x,y){const c=$('#fx'),g=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;let ps=[...Array(70)].map(()=>{const a=Math.random()*6.28,v=2+Math.random()*5;return{x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,l:60,c:`hsl(${Math.random()*360},90%,60%)`}});(function f(){g.clearRect(0,0,c.width,c.height);ps=ps.filter(p=>p.l-->0);ps.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.1;g.fillStyle=p.c;g.fillRect(p.x,p.y,4,4)});if(ps.length)requestAnimationFrame(f)})()}
addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||dlg.open||e.ctrlKey||e.metaKey)return;const k=e.key.toLowerCase(),sv=v=>{tab='cal';view=v;render()};

({n:()=>qnew($('.cr')||$('.fab')),t:()=>{cur=today();render()},arrowleft:()=>go(-1),arrowright:()=>go(1),d:()=>sv('day'),w:()=>sv('week'),m:()=>sv('month'),y:()=>sv('year'),',':()=>openSet(),p:()=>S.timer?tstop():tstart(),r:()=>openRep(),'/':()=>{e.preventDefault();tab='cal';render();$('#q').focus()}})[k]?.()});
if(SH){viewer()}else{render();tup();if(!SY().tok&&!localStorage.igoff)showLogin('in');setInterval(affTick,3e4);setInterval(tup,1000);sync();setInterval(()=>{if(!dd&&!edit&&!dr&&!dlg.open&&!document.activeElement?.classList?.contains('dia'))render()},6e4);syTick();addEventListener('focus',sync);['pointerdown','keydown','wheel'].forEach(n=>addEventListener(n,()=>{syAct=Date.now()},{passive:true}));addEventListener('online',()=>sync(1));addEventListener('visibilitychange',()=>{if(!document.hidden)sync()});if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})}
